<template>
  <div class="home-view">
    <NavBarVue />

    <b-row class="mt-2 m-1">
      <b-col>
        <p class="text-secondary">
          <b>Resumo Global: </b>
          <small style="font-size: 10pt" v-date-format="today"></small>
        </p>
      </b-col>
    </b-row>

    <b-row class="m-1">
      <b-col lg="3" md="4" sm="12" class="mb-2">
        <b-card bg-variant="secondary" text-variant="white">
          <b-row>
            <b-col cols="3" style="font-size: 2.5rem" class="text-center"
              ><b-icon
                icon="people-fill"
                class="rounded-circle bg-primary p-2"
                variant="light"
              ></b-icon
            ></b-col>
            <b-col>
              Mutuários<br /><b>{{ customers.length }}</b></b-col
            >
          </b-row>
        </b-card>
      </b-col>
      <b-col lg="3" md="4" sm="12" class="mb-2">
        <b-card bg-variant="success" text-variant="white">
          <b-row>
            <b-col cols="3" style="font-size: 2.5rem" class="text-center"
              ><b-icon
                icon="credit-card-fill"
                class="rounded-circle bg-primary p-2"
                variant="light"
              ></b-icon
            ></b-col>
            <b-col>
              Crédito desenbolsado<br /><b v-money-format="activeLoans" />
            </b-col>
          </b-row>
        </b-card>
      </b-col>
      <b-col lg="3" md="4" sm="12" class="mb-2">
        <b-card bg-variant="info" text-variant="white">
          <b-row>
            <b-col cols="3" style="font-size: 2.5rem" class="text-center"
              ><b-icon
                icon="calendar-plus-fill"
                class="rounded-circle bg-primary p-2"
                variant="light"
              ></b-icon
            ></b-col>
            <b-col>
              Crédito pendente<br /><b v-money-format="pendingLoans" />
            </b-col>
          </b-row>
        </b-card>
      </b-col>
      <b-col lg="3" md="4" sm="12" class="mb-2">
        <b-card bg-variant="danger" text-variant="white">
          <b-row>
            <b-col cols="3" style="font-size: 2.5rem" class="text-center"
              ><b-icon
                icon="x"
                class="rounded-circle bg-primary p-2"
                variant="light"
              ></b-icon
            ></b-col>
            <b-col>
              Crédito rejeitado<br /><b v-money-format="rejectedLoans" />
            </b-col>
          </b-row>
        </b-card>
      </b-col>
    </b-row>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import moment from "moment";
import FilterCustomer from "@/utils/filterCustomer";

export default {
  data: () => ({
    today: moment(),
    activeLoans: 0,
    pendingLoans: 0,
    rejectedLoans: 0,
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "company",
      "companyLoans",
      "accounts",
      "customers",
      "dueInstallments",
      "upcomingInstallments",
      "updatedPassword",
    ]),
  },

  watch: {
    companyLoans: function () {
      this.populateCompanyLoans();
    },
  },

  created() {
    this.checkPasswordStatus();
    console.log(this.companyLoans);
  },

  methods: {
    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    calculateDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays;
    },

    calculatePendingDays(dueDate) {
      const diffDays = this.today.diff(dueDate, "days");
      return diffDays;
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
      this.$router.replace("/customer");
    },

    filterLoans(amortizations) {
      const filteredLoansAmortization = amortizations.filter((a) => {
        return a.status == 0;
      });
      return filteredLoansAmortization;
    },

    getCustomer(accountNumber) {
      return FilterCustomer.filter(this.customers, accountNumber).customerName;
    },

    populateCompanyLoans() {
      // Disbursed Loans
      const disbursedLoan = this.companyLoans.filter((credit) => {
        return credit.status == 1;
      });
      this.activeLoans = disbursedLoan.reduce((sum, p) => sum + p.amount, 0);

      // Pending Loans
      const pendingLoan = this.companyLoans.filter((credit) => {
        return credit.status == 0;
      });
      this.pendingLoans = pendingLoan.reduce((sum, p) => sum + p.amount, 0);

      // Disbursed Loans
      const rejectedLoan = this.companyLoans.filter((credit) => {
        return credit.status == -1;
      });

      this.rejectedLoans = rejectedLoan.reduce((sum, p) => sum + p.amount, 0);
    },
  },
};
</script>
<style scoped></style>
